find:
if (/[^\u0021-\u007e]|[?#\\@]/.test(text)) return false;
if (!/^https?:\/\/[^/%]+(?:\/|$)/i.test(text)) return false;
let url: URL;
try {
  url = new URL(text);
} catch {
  return false;
}
return (url.protocol === 'http:' || url.protocol === 'https:') && url.username === '' && url.password === '';

replace:
if (!/^https?:\/\/[^/%]+(?:\/|$)/i.test(text)) return false;
let url: URL;
try {
  url = new URL(text);
} catch {
  return false;
}
return (url.protocol === 'http:' || url.protocol === 'https:') && url.username === '' && url.password === '' && !/[^\u0021-\u007e]|[?#\\@]/.test(url.href);

